window.t = function (key, vars, lang) {
  const idx = { tr: 0, en: 1, ar: 2 }[lang || window.UI_LANG || 'tr'];
  const e = window.I18N[key];
  let s = e ? (e[idx] || e[0]) : key;
  if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(vars[k]); });
  return s;
};
